//
//  Procedural Noise & Textures
//  Native Metal Shader - Perlin, Simplex, Fractals
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float noise_scale;
    float octaves;
    float persistence;
    float blend_amount;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Hash function for pseudo-random values
float hash(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

// 2D Value noise
float valueNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);

    // Smooth interpolation
    f = f * f * (3.0 - 2.0 * f);

    // Four corners
    float a = hash(i);
    float b = hash(i + float2(1.0, 0.0));
    float c = hash(i + float2(0.0, 1.0));
    float d = hash(i + float2(1.0, 1.0));

    // Bilinear interpolation
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Perlin-like noise
float perlinNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);

    // Quintic interpolation
    float2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);

    float a = hash(i);
    float b = hash(i + float2(1.0, 0.0));
    float c = hash(i + float2(0.0, 1.0));
    float d = hash(i + float2(1.0, 1.0));

    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Fractal Brownian Motion (fBm)
float fbm(float2 p, int octaves, float persistence) {
    float value = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;
    float maxValue = 0.0;

    for (int i = 0; i < octaves; i++) {
        value += perlinNoise(p * frequency) * amplitude;
        maxValue += amplitude;
        amplitude *= persistence;
        frequency *= 2.0;
    }

    return value / maxValue;
}

// Voronoi / Cellular noise
float voronoi(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);

    float minDist = 1.0;

    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            float2 neighbor = float2(x, y);
            float2 point = hash(i + neighbor) * float2(1.0) + neighbor;
            float dist = length(point - f);
            minDist = min(minDist, dist);
        }
    }

    return minDist;
}

// Turbulence
float turbulence(float2 p, int octaves) {
    float value = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;

    for (int i = 0; i < octaves; i++) {
        value += abs(perlinNoise(p * frequency)) * amplitude;
        amplitude *= 0.5;
        frequency *= 2.0;
    }

    return value;
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    float time = float(uniforms.FrameCount) * 0.01;
    float2 p = in.texCoord * uniforms.noise_scale;

    // Generate multiple noise patterns
    int octaves = int(uniforms.octaves);

    // Fractal Brownian Motion
    float noise1 = fbm(p + time * 0.1, octaves, uniforms.persistence);

    // Turbulence
    float noise2 = turbulence(p + time * 0.05, octaves);

    // Voronoi
    float noise3 = voronoi(p * 2.0);

    // Combine noises
    float3 noiseColor = float3(
        noise1,
        noise2 * 0.5 + 0.5,
        noise3
    );

    // Blend with original
    color.rgb = mix(color.rgb, noiseColor, uniforms.blend_amount);

    return color;
}

